// NOTES — un bloc par faction. Case vide ("") = rien n'est affiché.
// Ne pas supprimer de faction ni changer les noms de champs.
//   fr / en : précisions utiles en phrases courtes (ne pas recopier le texte des cartes)
//   statut  : "officiel" | "communautaire" | "a-verifier"

DATA.notes = {

  // Aliens
  ALI: { fr: "• Renvoie-les d’où ils viennent ! Renvoie les créatures dans la main des joueurs\n• Deux créatures sont faibles mais permettent de gagner 1 PV\n• Actions pour changer de base", en: "• Send them back where they came from! Returns minions to players' hands\n• Two minions are weak but let you gain 1 VP\n• Actions to change bases", statut: "a-verifier" },

  // Dinosaures
  DIN: { fr: "• Joue de grosses créatures\n• 7 créatures fortes et les autres le deviennent grâce à leur pouvoir\n• Augmente le pouvoir jusqu’à la fin de leur tour\n• Détruit les créatures généralement à 3 de forces ou moins", en: "• Plays big minions\n• 7 strong minions, and the others become strong thanks to their abilities\n• Boosts power until the end of the turn\n• Destroys minions, usually those with power 3 or less", statut: "a-verifier" },

  // Ninjas
  NIN: { fr: "• Joue des créatures spéciales avant la capture d’une base\n• Détruit les créatures ennemies\n• Détruit les actions affectées aux bases", en: "• Plays special minions before a base scores\n• Destroys enemy minions\n• Destroys actions played on bases", statut: "a-verifier" },

  // Pirates
  PIR: { fr: "• Déplace les créatures\n• Détruit les créatures de force 2 ou moins\n• Déplace les créatures vers une autre base après la résolution d’une base\n• Gagne temporairement de la force supplémentaire", en: "• Moves minions\n• Destroys minions with power 2 or less\n• Moves minions to another base after a base scores\n• Temporarily gains extra power", statut: "a-verifier" },

  // Robots
  ROB: { fr: "• 18 (contre 10) petites créatures et seulement 2 actions\n• Joue beaucoup de créatures supplémentaires par tour\n• Beaucoup de créatures se donnent mutuellement un peu de force supplémentaire\n• Tire des cartes supplémentaires", en: "• 18 (vs. the usual 10) small minions and only 2 actions\n• Plays many extra minions per turn\n• Many minions give each other a little extra power\n• Draws extra cards", statut: "a-verifier" },

  // Petit Peuple
  PTP: { fr: "• Limite le choix des adversaires\n• Force les joueurs à abandonner leurs cartes\n• Élimine les actions adverses\n• Joue des créatures supplémentaires\n• Détruit les créatures faibles", en: "• Limits your opponents' choices\n• Forces players to give up their cards\n• Eliminates opponents' actions\n• Plays extra minions\n• Destroys weak minions", statut: "a-verifier" },

  // Sorciers
  SOR: { fr: "• Pioche des cartes supplémentaires\n• Force les joueurs à abandonner leurs cartes\n• 4 des créatures ont des forces inférieures à la moyenne\n• Élimine les actions adverses\n• Joue des créatures supplémentaires\n• Détruit les créatures faibles", en: "• Draws extra cards\n• Forces players to give up their cards\n• 4 of the minions have below-average power\n• Eliminates opponents' actions\n• Plays extra minions\n• Destroys weak minions", statut: "a-verifier" },

  // Zombies
  ZOM: { fr: "• Ressuscité d’entre les morts\n• Défausse tes cartes\n• Récupère les cartes de ta défausse dans ta main\n• Joue des créatures supplémentaires depuis ta défausse\n• 3 des créatures ont des forces inférieures à la moyenne", en: "• Back from the dead\n• Discards your cards\n• Returns cards from your discard pile to your hand\n• Plays extra minions from your discard pile\n• 3 of the minions have below-average power", statut: "a-verifier" },

  // Cavalerie Ours
  CAO: { fr: "• Déplace les créatures ennemies\n• Détruit les créatures après leur déplacement\n• Tes créatures gagnent en forces supplémentaires\n• Joue des créatures supplémentaires\n• Créer des créatures indestructibles", en: "• Moves enemy minions\n• Destroys minions after they move\n• Your minions gain extra power\n• Plays extra minions\n• Creates indestructible minions", statut: "a-verifier" },

  // Fantômes
  FAN: { fr: "• Défausse tes cartes pour tuer les créatures ennemies et gagner en force ou reconstituer ta main\n• Avec 2 cartes ou moins, gagne des PV, de la force supplémentaire, des renvois de créatures et des créatures à jouer en plus", en: "• Discards your cards to kill enemy minions and gain power, or to refill your hand\n• With 2 cards or fewer, gains VP, extra power, minion returns and extra minions to play", statut: "a-verifier" },

  // Plantes Carnivores
  PLC: { fr: "• Pioche des cartes supplémentaires, joue des créatures supplémentaires, remplace les faibles créatures par des plus fortes\n• Diminue les forces des adversaires\n• Empêche les créatures de se déplacer et de retourner à la main", en: "• Draws extra cards, plays extra minions, replaces weak minions with stronger ones\n• Lowers opponents' power\n• Prevents minions from moving or returning to hand", statut: "a-verifier" },

  // Steampunks
  STE: { fr: "• Joue des actions sur les bases et ajoute de la force entre autres\n• Déplace tes actions de base en base\n• Place les actions de ta défausse vers ta main", en: "• Plays actions on bases and adds power, among other things\n• Moves your actions from base to base\n• Returns actions from your discard pile to your hand", statut: "a-verifier" },

  // Grands Anciens
  GRA: { fr: "• Distribue des cartes Démence aux adversaires et profite d’eux s’ils les refusent\n• Place des jetons de force en fonction des cartes Démence que les adversaires ont en main\n• Replace des créatures de ta défausse sur ta pioche ou en jeu\n• Une créature de force 10 immunisée aux cartes adverses, mais coûteuse à jouer", en: "• Hands Madness cards to opponents and profits from them if they refuse\n• Places power counters based on the Madness cards in opponents' hands\n• Returns minions from your discard pile to your deck or into play\n• A power-10 minion immune to opposing cards, but costly to play", statut: "a-verifier" },

  // Innsmouth
  INN: { fr: "• 10 exemplaires de la même créature de force 2, qui va chercher ses semblables dans la pioche\n• Joue des créatures supplémentaires portant le même nom que des créatures en jeu\n• Augmente temporairement la force des créatures de force 2 ou moins\n• Protège les créatures faibles des cartes adverses et les ramène en main après la conquête d’une base\n• Pioche des cartes (et quelques Démences) quand 3 créatures du même nom sont sur une base", en: "• 10 copies of the same power-2 minion, which fetches its fellow copies from your deck\n• Plays extra minions that share a name with minions in play\n• Temporarily boosts the power of minions with power 2 or less\n• Shields weak minions from opposing cards and returns them to hand after a base scores\n• Draws cards (and a few Madness cards) when 3 minions with the same name are on a base", statut: "a-verifier" },

  // Serviteurs de Cthulhu
  SDC: { fr: "• Pioche des cartes Démence en échange de nombreuses actions supplémentaires\n• Replace des actions et des créatures de force 3 ou moins de ta défausse sur ta pioche\n• Détruit des créatures ennemies\n• Gagne des PV directement et de la force avant la conquête d’une base\n• Refile tes cartes Démence aux adversaires", en: "• Draws Madness cards in exchange for many extra actions\n• Puts actions and minions with power 3 or less from your discard pile back on your deck\n• Destroys enemy minions\n• Gains VP directly and extra power before a base scores\n• Passes your Madness cards on to opponents", statut: "a-verifier" },

  // Université Miskatonic
  MIS: { fr: "• Pioche des cartes Démence et les joue comme des actions supplémentaires\n• Défausse ou renvoie des cartes Démence pour jouer des actions et des créatures supplémentaires\n• Donne de la force jusqu’à la fin du tour en échange de cartes Démence\n• Détruit la créature la plus forte d’une base avant sa conquête, ou les actions posées sur une base\n• Pioche des cartes supplémentaires en plaçant des cartes sous la pioche", en: "• Draws Madness cards and plays them as extra actions\n• Discards or returns Madness cards to play extra actions and minions\n• Gives power until the end of the turn in exchange for Madness cards\n• Destroys the strongest minion on a base before it scores, or the actions on a base\n• Draws extra cards by putting cards on the bottom of your deck", statut: "a-verifier" },

  // Métamorphes
  MET: { fr: "• Copie les pouvoirs ennemis\n• Détruit les créatures ou remélange-les dans la pioche pour retrouver dans ta pioche des créatures supplémentaires à jouer\n• Copie les forces des ennemis\n• Gagne en force", en: "• Copies enemy abilities\n• Destroys minions, or reshuffles them into the deck to draw extra minions to play\n• Copies enemy power\n• Gains power", statut: "a-verifier" },

  // Singes Cyborgs
  SIC: { fr: "Joue sur une créature des actions pour augmenter sa force, la rendre invincible, la déplacer, et pour avoir des cartes supplémentaires", en: "Plays actions on a minion to boost its power, make it invincible, move it, and draw extra cards", statut: "a-verifier" },

  // Super Espions
  SUE: { fr: "• Regarde en avance ta pioche pour manipuler les cartes que tu as\n• Oblige tes adversaires de défausser ou de mettre leur carte en haut de leur pile\n• Joue des actions supplémentaires", en: "• Looks ahead at your deck to manipulate the cards you get\n• Forces opponents to discard or put their card on top of their deck\n• Plays extra actions", statut: "a-verifier" },

  // Voyageurs du Temps
  VDT: { fr: "• Ramène tes créatures dans ta pile après avoir résolu une base\n• Met des cartes de ta défausse à ta main\n• Utilise 2x les pouvoirs des créatures\n• Renvoie les cartes ennemies et les tiennes dans la main\n• Joue des actions supplémentaires", en: "• Returns your minions to your deck after a base scores\n• Puts cards from your discard pile into your hand\n• Uses minion abilities twice\n• Returns enemy cards and your own to hand\n• Plays extra actions", statut: "a-verifier" },

  // Fourmis Géantes
  FOU: { fr: "Place 1 ou 2 jeton +1 force sur tes créatures et transferts-les librement entre tes créatures", en: "Places 1 or 2 +1 power counters on your minions and moves them freely between your minions", statut: "a-verifier" },

  // Loups-Garous
  LOU: { fr: "• Augmente la force jusqu’à la fin du tour\n• Détruit les créatures plus faibles que les tiennes", en: "• Boosts power until the end of the turn\n• Destroys minions weaker than yours", statut: "a-verifier" },

  // Savants Fous
  SAF: { fr: "• Ajoute continuellement des jetons de forces à tes créatures\n• Créer des créatures indestructibles\n• Joue des créatures supplémentaires", en: "• Continually adds power counters to your minions\n• Creates indestructible minions\n• Plays extra minions", statut: "a-verifier" },

  // Vampires
  VAM: { fr: "• Détruit des faibles créatures et gagne des jetons de forces\n• Rappelle des faibles créatures depuis ta défausse", en: "• Destroys weak minions and gains power counters\n• Brings back weak minions from your discard pile", statut: "a-verifier" },

  // Chatons
  CHA: { fr: "• Réduit la force des ennemis\n• Prend le contrôle des ennemis faibles (et parfois des forts)\n• Détruit les créatures que tu contrôles en échange d’une pioche supplémentaire, actions et créatures", en: "• Reduces enemy power\n• Takes control of weak enemies (and sometimes strong ones)\n• Destroys minions you control in exchange for extra draws, actions and minions", statut: "a-verifier" },

  // Fées
  FEE: { fr: "• La plupart des cartes donnent 2 options, connaître les cartes à venir, actions supplémentaires ou augmente/réduit la force des créatures\n• Joue les actions ennemies contre eux", en: "• Most cards give 2 options: see upcoming cards, extra actions, or raise/lower minions' power\n• Plays enemy actions against them", statut: "a-verifier" },

  // Poneys Magiques
  PON: { fr: "Les créatures augmentent leur force quand ils sont sur la même base avec de nouvelles capacités comme jouer plus de créatures, se déplacer ou piocher de nouvelles cartes", en: "Minions gain power when they share a base, with new abilities such as playing more minions, moving or drawing new cards", statut: "a-verifier" },

  // Princesses
  PRI: { fr: "• 6 créatures de forces 5\n• Pioche des cartes supplémentaires\n• Déplace tes créatures\n• Replace les créatures défaussées dans ta pioche\n• Détruit les créatures de force <= 2\n• Gagne +1 en force en jouant avec des actions sur les créatures", en: "• 6 minions with power 5\n• Draws extra cards\n• Moves your minions\n• Puts discarded minions back into your deck\n• Destroys minions with power 2 or less\n• Gains +1 power when playing actions on minions", statut: "a-verifier" },

  // Geeks
  GEE: { fr: "• Immunisé contre les effets des cartes adverses\n• Manipule la main des adversaires\n• Défausse tes cartes pour de nouvelles", en: "• Immune to the effects of opposing cards\n• Manipulates opponents' hands\n• Discards your cards for new ones", statut: "a-verifier" },

  // Elfes
  ELF: { fr: "• Aide les autres joueurs (cartes, force) pour mieux en profiter toi-même\n• Pioche des cartes supplémentaires et remélange les défausses dans les pioches\n• Prend le contrôle de créatures adverses de force 3 ou moins en échange d’une des tiennes\n• Déplace tes créatures (et parfois celles des adversaires) avant la conquête d’une base\n• Échange des cartes avec les mains adverses et prend 1 PV à l’adversaire que tu as aidé à gagner une base", en: "• Helps other players (cards, power) to profit from it yourself\n• Draws extra cards and shuffles all discard piles back into the decks\n• Takes control of enemy minions with power 3 or less in exchange for one of yours\n• Moves your minions (and sometimes the enemy's) before a base scores\n• Swaps cards with opponents' hands and takes 1 VP from the opponent you helped win a base", statut: "a-verifier" },

  // Guerriers
  GUE: { fr: "• Joue et détruit des monstres sur les bases\n• Place des jetons de force +1 chaque fois qu’un monstre est détruit\n• Détruit des monstres pour jouer des actions supplémentaires, ajouter leur force ou jouer les trésors obtenus\n• Joue des actions sur tes créatures pour augmenter leur force\n• Détruit les créatures adverses de force imprimée 2 ou moins", en: "• Plays and destroys monsters on bases\n• Places +1 power counters each time a monster is destroyed\n• Destroys monsters to play extra actions, add their power or play the treasures you get\n• Plays actions on your minions to increase their power\n• Destroys enemy minions with printed power 2 or less", statut: "a-verifier" },

  // Halfelins
  HAL: { fr: "• Toutes les créatures permettent d’en jouer une supplémentaire, selon la force ou la présence sur la base\n• Pioche des cartes ou des créatures en jouant sur une base\n• Pose toutes les créatures de ta main sur une base en un seul tour\n• Replace des créatures de ta défausse sur ta pioche ou évite qu’une créature n’y aille\n• Protège les créatures d’une base des actions adverses", en: "• Every minion lets you play an extra minion, depending on power or presence on the base\n• Draws cards or minions while playing on a base\n• Drops every minion in your hand onto one base in a single turn\n• Puts minions from your discard pile back on your deck, or keeps a minion from going there\n• Protects the minions on a base from opposing actions", statut: "a-verifier" },

  // Magiciens
  MAG: { fr: "• Défausse des cartes pour jouer des créatures et des actions supplémentaires\n• Pioche de nombreuses cartes en échange de défausses\n• Joue, déplace ou prend le contrôle de monstres\n• Donne +3 ou -3 de force, ou des jetons +1, en échange de défausses\n• Détruit des créatures de force 3 ou moins, remet des cartes de ta défausse dans ta pioche et fait défausser les adversaires", en: "• Discards cards to play extra minions and actions\n• Draws many cards in exchange for discards\n• Plays, moves or takes control of monsters\n• Gives +3 or -3 power, or +1 counters, in exchange for discards\n• Destroys minions with power 3 or less, shuffles cards from your discard pile back into your deck and makes opponents discard", statut: "a-verifier" },

  // Nains
  NAI: { fr: "• Pioche des trésors depuis la pioche ou la défausse des trésors, et fouille la pioche pour y trouver des actions\n• Joue des actions-trésors sur tes créatures, dont certaines gagnent +2 de force par trésor\n• Joue des trésors comme cartes supplémentaires, ainsi que des actions supplémentaires\n• Augmente ou diminue de 4 le seuil de conquête d’une base\n• Détruit une action", en: "• Draws treasures from the treasure deck or its discard pile, and digs through the deck for actions\n• Plays treasure actions on your minions, some of which gain +2 power per treasure\n• Plays treasures as extra cards, plus extra actions\n• Raises or lowers a base's breakpoint by 4\n• Destroys an action", statut: "a-verifier" },

  // Orques
  ORQ: { fr: "• Augmente la force de tes créatures (+1 pour toutes tes autres créatures, jetons +1, actions sur les bases)\n• Détruit les créatures plus faibles que les tiennes ou de force 3 ou moins\n• Réduit le seuil de conquête des bases et gagne 1 PV quand une base est largement dépassée\n• Protège tes créatures (immunité ou indestructibilité) et réduit la force ou la main des adversaires\n• Déplace tes créatures vers une base où tu en as déjà", en: "• Boosts your minions' power (+1 to all your other minions, +1 counters, actions on bases)\n• Destroys minions weaker than yours or with power 3 or less\n• Lowers bases' breakpoints and gains 1 VP when a base is well exceeded\n• Protects your minions (immunity or indestructibility) and reduces opponents' power or hand size\n• Moves your minions to a base where you already have one", statut: "a-verifier" },

  // Prêtres
  PRE: { fr: "• Remet des cartes de ta défausse dans ta pioche ou ta main, et met des actions en stase pour les jouer plus tard\n• Joue et manipule des monstres morts-vivants\n• Annule les pouvoirs d’une créature ou l’empêche d’ajouter sa force à une base\n• Prend le contrôle de créatures de force 3 ou moins ou de monstres morts-vivants\n• Déplace tes créatures, notamment après la conquête d’une base", en: "• Returns cards from your discard pile to your deck or hand, and puts actions into stasis to play them later\n• Plays and manipulates undead monsters\n• Cancels a minion's abilities or stops it from adding its power to a base\n• Takes control of minions with power 3 or less or of undead monsters\n• Moves your minions, notably after a base scores", statut: "a-verifier" },

  // Voleurs
  VOL: { fr: "• Pioche des trésors et des cartes en grand nombre, et augmente la taille maximale de ta main\n• Défausse des trésors pour gagner des PV, jouer des cartes supplémentaires ou donner de la force\n• Vole des actions et des cartes aux adversaires (main, défausse ou pioche)\n• Détruit des créatures de force 3 ou moins (plus par carte défaussée) et gagne des jetons de force\n• Gagne des PV directement ou prend 1 PV à un adversaire, avant ou après la conquête d’une base", en: "• Draws treasures and plenty of cards, and raises your maximum hand size\n• Discards treasures to gain VP, play extra cards or give power\n• Steals actions and cards from opponents (hand, discard pile or deck)\n• Destroys minions with power 3 or less (more per card discarded) and gains power counters\n• Gains VP directly or takes 1 VP from an opponent, before or after a base scores", statut: "a-verifier" },

  // Changeformers
  CHF: { fr: "• Sacrifie ta force pour des pouvoirs comme se déplacer, des actions supplémentaires et détruire\n• Déplace tes créatures\n• Sacrifie tes pouvoirs pour gagner en force", en: "• Sacrifices your power for abilities such as moving, extra actions and destroying\n• Moves your minions\n• Sacrifices your abilities to gain power", statut: "a-verifier" },

  // Chevaliers des Étoiles
  CDE: { fr: "• Augmente ta force avec des actions\n• Joue des cartes supplémentaires\n• Utilise des pouvoirs spéciaux avant la conquête d’une base", en: "• Boosts your power with actions\n• Plays extra cards\n• Uses special abilities before a base scores", statut: "a-verifier" },

  // Squatteurs de Trône
  SDT: { fr: "• Donne le contrôle de tes créatures pour jouer des créatures supplémentaires et des PV s’ils gagnent une conquête\n• Reprend le contrôle pour des actions supplémentaires ou avant une conquête de base\n• Détruit les autres créatures", en: "• Gives away control of your minions to play extra minions and gain VP if they win a base\n• Takes back control for extra actions or before a base is captured\n• Destroys other minions", statut: "a-verifier" },

  // Voyageurs de l'Espace
  VDE: { fr: "• Renvoie tes créatures ou celles des autres dans leur main\n• Joue avant une conquête ou pour jouer une autre créature\n• Transfert les effets adverses vers la créature la plus faible\n• Déplace les créatures\n• Découvre de nouvelles bases", en: "• Returns your minions or others' to their hand\n• Plays before a base scores or to play another minion\n• Transfers opposing effects to the weakest minion\n• Moves minions\n• Discovers new bases", statut: "a-verifier" },

  // Dragons
  DRA: { fr: "• Rend les bases plus difficiles à conquérir pour tes adversaires\n• Décroît les PV des bases capturées par tes adversaires\n• Réduit les points de conquêtes\n• Joue des créatures avant la résolution d’une base\n• Pioche des cartes supplémentaires", en: "• Makes bases harder for your opponents to capture\n• Lowers the VP of bases captured by your opponents\n• Reduces conquest points\n• Plays minions before a base scores\n• Draws extra cards", statut: "a-verifier" },

  // Mythologies Grecques
  MYG: { fr: "• Gagne des jetons de forces ou de la force jusqu’à la fin de ton tour quand tu joues des actions\n• Joue des créatures de force 2 en tant qu’action\n• Joue des actions supplémentaires", en: "• Gains power counters or power until the end of your turn when you play actions\n• Plays power-2 minions as actions\n• Plays extra actions", statut: "a-verifier" },

  // Requins
  REQ: { fr: "• Quand les créatures sont détruites, gagne des pouvoirs comme jouer des créatures supplémentaires, ajouter des jetons de force +1, jouer des cartes supplémentaires\n• Détruit les créatures de force <= 3\n• Joue des cartes supplémentaires", en: "• When minions are destroyed, gains powers such as playing extra minions, adding +1 power counters, playing extra cards\n• Destroys minions with power 3 or less\n• Plays extra cards", statut: "a-verifier" },

  // Super-Héros
  SUH: { fr: "• Transforme les créatures de forces 2 en forces 5 avec de nouveaux pouvoirs et talents\n• Renvoie tes créatures de la défausse sur la pioche ou dans ta main\n• Gagne de la force jusqu’à la fin du tour\n• Rend les créatures invincibles", en: "• Turns power-2 minions into power-5 ones with new abilities and talents\n• Returns your minions from the discard pile to your deck or hand\n• Gains power until the end of the turn\n• Makes minions invincible", statut: "a-verifier" },

  // Tornades
  TOR: { fr: "• Déplace toutes les créatures de tout le monde vers une autre base\n• Déplace tes créatures de force 2 vers une base avant une conquête\n• Échange la place de 2 créatures\n• Détruit ou transfert les actions des adversaires", en: "• Moves everyone's minions to another base\n• Moves your power-2 minions to a base before it scores\n• Swaps the places of 2 minions\n• Destroys or transfers opponents' actions", statut: "a-verifier" },

  // Explorateurs
  EXP: { fr: "• Manipule l’ordre des bases dans la pioche à ton avantage\n• Joue des créatures supplémentaires dans les nouvelles bases\n• Déplace tes créatures vers ou depuis les bases et gagnent temporairement de la force", en: "• Manipulates the order of the bases in the deck to your advantage\n• Plays extra minions on the new bases\n• Moves your minions to or from bases, and they temporarily gain power", statut: "a-verifier" },

  // Grands-Mères
  GME: { fr: "• Regarde les cartes au-dessus de la pioche et décide si tu souhaites les conserver ou les envoyer au fond du paquet\n• Joue des actions supplémentaires\n• Met les cartes de ta main sous la pioche pour de nouvelles cartes", en: "• Looks at the top cards of your deck and decides whether to keep them or send them to the bottom\n• Plays extra actions\n• Puts cards from your hand under your deck to get new ones", statut: "a-verifier" },

  // Oursons
  OUR: { fr: "• Joue des créatures en plus\n• Même force que la plus forte créature en jeu\n• Gagne de la force quand les autres jouent ou déplacent leurs créatures sur une base où tu es\n• Pioche des cartes\n• Annule les pouvoirs des adversaires", en: "• Plays extra minions\n• Same power as the strongest minion in play\n• Gains power when others play or move minions to a base where you are present\n• Draws cards\n• Cancels opponents' abilities", statut: "a-verifier" },

  // Rockstars
  ROK: { fr: "• Récupère tes 5 créatures à force 2 pour les jouer en plus\n• Pioche des cartes supplémentaires sur une base à 21 ou plus\n• Déplace les créatures vers une base plus grosse\n• Pioche des cartes supplémentaires\n• Donne +1 force à toutes tes créatures", en: "• Retrieves your 5 power-2 minions to play them as extras\n• Draws extra cards at a base with 21 power or more\n• Moves minions to a bigger base\n• Draws extra cards\n• Gives +1 power to all your minions", statut: "a-verifier" },

  // Kaijū
  KAI: { fr: "• Tes actions ont de la puissance\n• Gagne de la force grâce aux actions des bases\n• Détruit les cartes des autres joueurs\n• Joue des actions supplémentaires\n• Réduit les points de conquêtes des bases", en: "• Your actions have power\n• Gains power from base actions\n• Destroys other players' cards\n• Plays extra actions\n• Reduces the conquest points of bases", statut: "a-verifier" },

  // Monstrapoches
  MON: { fr: "Joue de faibles créatures qui vont sous la pioche à la fin du tour et qui offre un large choix de pouvoirs lors des pioches comme des accroissements de forces et une boîte à outils de pouvoirs", en: "Plays weak minions that go under the deck at the end of the turn and offer a wide range of abilities when drawn, such as power boosts and a toolbox of powers", statut: "a-verifier" },

  // Petites Magiciennes
  PMA: { fr: "• Utilise les capacités qui sont meilleurs plus il y a de créatures dans la même base\n• Récupère ta meilleure créature\n• Déplace les créatures\n• Joue des créatures supplémentaires", en: "• Uses abilities that get better the more minions share a base\n• Retrieves your best minion\n• Moves minions\n• Plays extra minions", statut: "a-verifier" },

  // Super Combattants
  SUC: { fr: "• Joue des créatures spéciales et des actions avant la conquête d’une base\n• Gagne de la force jusqu’à la fin du tour", en: "• Plays special minions and actions before a base scores\n• Gains power until the end of the turn", statut: "a-verifier" },

  // Danseurs Disco
  DIS: { fr: "• Bénéficier des cartes actions standards\n• Copie les effets des actions standards\n• Gagne +1 jeton de force\n• Joue des actions supplémentaires\n• Récupère les cartes depuis ou qui vont vers la défausse", en: "• Benefits from standard action cards\n• Copies the effects of standard actions\n• Gains a +1 power counter\n• Plays extra actions\n• Retrieves cards from, or sends cards to, the discard pile", statut: "a-verifier" },

  // Justiciers
  JUS: { fr: "• 7 unique créature de force 4\n• Réagit immédiatement après l’effet d’un joueur\n• Gagne 1 à 3 de forces jusqu’à la fin du tour\n• Pioche des cartes", en: "• 7 unique minions with power 4\n• Reacts immediately after another player's effect\n• Gains 1 to 3 power until the end of the turn\n• Draws cards", statut: "a-verifier" },

  // Maîtres Kung-Fu
  KUN: { fr: "• Transfert tes jetons de forces\n• Place des jetons de forces sur tes créatures\n• Détruit les créatures", en: "• Transfers your power counters\n• Places power counters on your minions\n• Destroys minions", statut: "a-verifier" },

  // Routiers
  ROU: { fr: "• Transfert des actions d’une base vers une autre\n• Place des actions sur les bases\n• Déplace tes créatures\n• Les actions des bases augmentent ta force", en: "• Transfers actions from one base to another\n• Places actions on bases\n• Moves your minions\n• Base actions increase your power", statut: "a-verifier" },

  // Anciens Égyptiens
  EGY: { fr: "• Place des cartes face cachés, rendant difficiles de savoir ce que c’est pour l’adversaire\n• Conserve des créatures de force 2 en les jouant faces cachées", en: "• Places cards face down, making it hard for opponents to know what they are\n• Keeps power-2 minions by playing them face down", statut: "a-verifier" },

  // Cow-Boys
  COW: { fr: "• Une créature peut faire un duel contre une autre, les 2 joueurs peuvent jouer une action face cachée pour ajouter de la force\n• La créature avec la plus grande force gagne et le perdant est normalement détruit", en: "• A minion can duel another; both players may play an action face down to add power\n• The minion with the highest power wins and the loser is normally destroyed", statut: "a-verifier" },

  // Samouraïs
  SAM: { fr: "Quand une créature va faire la défausse, tu peux piocher une carte supplémentaire, jouer une carte action, avoir un boost de force ou même des PV", en: "When a minion goes to the discard pile, you can draw an extra card, play an action, get a power boost or even gain VP", statut: "a-verifier" },

  // Vikings
  VIK: { fr: "• Vole les cartes depuis la pioche ou la main de ton adversaire\n• Gagne temporairement de la force en plaçant des cartes au-dessus de ta pioche", en: "• Steals cards from your opponent's deck or hand\n• Temporarily gains power by placing cards on top of your deck", statut: "a-verifier" },

  // Dream Team
  DRE: { fr: "Cette faction réunis des cartes de pleins d'autres factions existantes", en: "This faction brings together cards from many other existing factions", statut: "a-verifier" },

  // Luchadors
  LUC: { fr: "• Jouez des actions sur les sbires des autres qui vous profitent\n• Cherchez ces actions dans votre deck/défausse pour les ajouter à votre main\n• Obtenez des avantages de puissance en ayant ces actions sur vos ennemis", en: "• Play actions on other players' minions that benefit you\n• Search your deck/discard pile for those actions to add them to your hand\n• Gain power bonuses by having those actions on your enemies", statut: "a-verifier" },

  // Mousquetaires
  MOU: { fr: "• Jouez des cartes qui affectent directement vos sbires, puis jouez une action supplémentaire\n• Profitez des actions qui vous affectent directement\n• Piochez des cartes supplémentaires", en: "• Play cards that directly affect your minions, then play an extra action\n• Benefit from actions that directly affect you\n• Draw extra cards", statut: "a-verifier" },

  // Police Montée
  POM: { fr: "• Déplacez-vous vers des bases où se trouvent des sbires d'autres joueurs\n• Augmentez votre puissance là où des sbires d'autres joueurs sont présents", en: "• Move to bases where other players' minions are\n• Increase your power where other players' minions are present", statut: "a-verifier" },

  // Sumos
  SUM: { fr: "• Défaussez des cartes pour gagner de la puissance et des marqueurs de puissance\n• Déplacez les sbires des autres joueurs loin des bases où vous avez des sbires\n• Piochez des cartes supplémentaires", en: "• Discard cards to gain power and power counters\n• Move other players' minions away from bases where you have minions\n• Draw extra cards", statut: "a-verifier" },

  // Knights of the Round Table
  KRT: { fr: "• Faction avec beaucoup de mouvement\n• Se renforce en bougant\n• Gagne des PV directement", en: "• A faction with lots of movement\n• Gets stronger by moving\n• Gains VP directly", statut: "a-verifier" },

  // Avengers
  AVE: { fr: "• Seulement 6 sbires, tous de force 5, chacun avec un pouvoir distinct (détruire un sbire de force 5 ou moins, piocher 3 cartes, donner de la force, déplacer des sbires)\n• Pioche, trie le haut de ta pioche et remélange des sbires de ta défausse pour retrouver tes sbires et tes actions\n• Donne de la force jusqu’à la fin du tour à tes sbires (jusqu’à +3) et en retire aux adversaires avant la conquête d’une base\n• Détruit des sbires de force 3 ou moins, des modificateurs de base ou même une base entière, et protège tes sbires des actions adverses\n• Déplace tes sbires, notamment avant la conquête d’une base ; plusieurs actions sont renforcées quand le sbire correspondant est en jeu", en: "• Only 6 minions, all power 5, each with its own ability (destroy a power-5-or-less minion, draw 3 cards, give power, move minions)\n• Draws, sorts the top of your deck and shuffles minions from your discard pile back in to find your minions and actions\n• Gives your minions power until the end of the turn (up to +3) and takes power away from opponents before a base scores\n• Destroys minions with power 3 or less, base modifiers or even a whole base, and protects your minions from opposing actions\n• Moves your minions, notably before a base scores; several actions get stronger when the matching minion is in play", statut: "a-verifier" },

  // Hydra
  HYD: { fr: "• Inonde les bases de petits sbires : 6 agents de force 2 font jouer jusqu’à 2 sbires de force 2 ou moins en plus quand ils sont détruits\n• Détruit tes propres sbires (talent et actions) pour piocher : 1 carte par sbire détruit, ou autant de cartes que sa force\n• Cherche dans ta pioche et récupère de ta défausse des sbires de force 2 ou moins, en main ou sur la pioche\n• Gagne de la force grâce aux petits sbires de la base (+1 par autre sbire de force imprimée 2 ou moins) et +2 après une destruction sur la base", en: "• Floods bases with small minions: 6 power-2 agents let you play up to 2 extra minions of power 2 or less when they are destroyed\n• Destroys your own minions (talent and actions) to draw cards: 1 card per destroyed minion, or as many cards as its power\n• Searches your deck and recovers minions with power 2 or less from your discard pile, into your hand or onto your deck\n• Gains power from the small minions on the base (+1 per other minion with printed power 2 or less) and +2 after a destruction on the base", statut: "a-verifier" },

  // Kree
  KRE: { fr: "• Joue des actions supplémentaires grâce à plusieurs sbires et actions\n• Pioche des cartes supplémentaires, surtout des actions, et replace des actions de ta défausse sur ta pioche\n• Gagne de la force à chaque action jouée : un sbire de force 5 donne +1 à un de tes autres sbires, et quatre sbires de force 2 gagnent +2 après 2 actions jouées dans le tour\n• Donne de la force à tes sbires avec des actions : +1 ou +2 jusqu’à la fin du tour, ou +3 permanent avec deux modificateurs de sbire\n• Aucun déplacement, aucune destruction ni contrôle : la force dépend des actions jouées", en: "• Plays extra actions through several minions and actions\n• Draws extra cards, mostly actions, and puts actions from your discard pile back on your deck\n• Gains power each time you play an action: a power-5 minion gives +1 to one of your other minions, and four power-2 minions gain +2 after 2 actions played in the turn\n• Boosts your minions' power with actions: +1 or +2 until the end of the turn, or a permanent +3 with two minion modifiers\n• No movement, destruction or control: its power depends on the actions you play", statut: "a-verifier" },

  // Masters of Evil
  MOE: { fr: "• Gagne des PV directement par de nombreux effets : en détruisant tes propres sbires, en déplaçant un sbire sur une base où tu en as déjà 4, en détruisant un sbire adverse, ou quand une base marque\n• Ses sbires gagnent de la force ou font piocher selon le nombre de PV que tu as (par tranche de 4 PV)\n• Détruit tes propres sbires de force 4 ou plus, ou des paires de sbires identiques, pour gagner 1 PV\n• Détruit des sbires adverses de force 3 ou moins, ou plus faibles que ta force totale sur la base\n• Protège tes sbires de la destruction par les cartes adverses et réutilise un modificateur de base qui change de base après la conquête", en: "• Gains VP directly through many effects: by destroying your own minions, by moving a minion to a base where you already have 4, by destroying an enemy minion, or when a base scores\n• Its minions gain power or draw cards depending on how many VP you have (per 4 VP)\n• Destroys your own minions with power 4 or more, or pairs of identical minions, to gain 1 VP\n• Destroys enemy minions with power 3 or less, or weaker than your total power on the base\n• Protects your minions from being destroyed by opposing cards and reuses a base modifier that moves to another base after a base scores", statut: "a-verifier" },

  // S.H.I.E.L.D.
  SHI: { fr: "• Joue des sbires supplémentaires sur la même base grâce à 4 sbires et 4 actions, dont 2 modificateurs de base\n• Gagne de la force en regroupant ses sbires : +1 pour les agents de force 2 accompagnés, +1 pour les sbires de force 4 à chaque sbire joué sur leur base, et +1 à tous tes sbires avec une action\n• Pioche une carte par sbire que tu as sur une base\n• Déplace jusqu’à 2 de tes sbires vers une base, et détruit une action posée sur une base ou un sbire de force 3 ou moins\n• Remélange tes sbires d’une base dans ta pioche après sa conquête pour piocher une carte", en: "• Plays extra minions on the same base thanks to 4 minions and 4 actions, including 2 base modifiers\n• Gains power by grouping its minions: +1 for power-2 agents with company, +1 for power-4 minions each time a minion is played on their base, and +1 to all your minions with an action\n• Draws a card for each minion you have on a base\n• Moves up to 2 of your minions to a base, and destroys an action placed on a base or a minion with power 3 or less\n• Shuffles your minions on a base back into your deck after it scores to draw a card", statut: "a-verifier" },

  // Sinister Six
  SIS: { fr: "• Abaisse le seuil de conquête des bases (jusqu’à 4 de moins) avec des sbires et des actions pour marquer plus vite\n• Joue beaucoup d’actions posées sur les bases (7 sur 20) et les réutilise : Mysterio en joue une en plus, Vulture en remet une de ta défausse sur ta pioche\n• Gagne de la force quand le seuil d’une base est de 19 ou moins : +2 pour Sandman, +3 pour Reroute the Power\n• Réduit la force des adversaires, les empêche d’utiliser leurs capacités spéciales ou annule les capacités d’une base à seuil bas\n• Remélange tes sbires d’une base dans les pioches après sa conquête et pioche une carte quand le seuil est bas", en: "• Lowers bases' breakpoints (by up to 4) with minions and actions to score faster\n• Plays plenty of actions on bases (7 out of 20) and reuses them: Mysterio plays one extra, Vulture puts one from your discard pile back on your deck\n• Gains power when a base's breakpoint is 19 or less: +2 for Sandman, +3 for Reroute the Power\n• Reduces opponents' power, stops them from using special abilities, or cancels a base's abilities on low-breakpoint bases\n• Shuffles your minions on a base back into the decks after it scores and draws a card when the breakpoint is low", statut: "a-verifier" },

  // Spider-Verse
  SPI: { fr: "• Joue ses sbires et ses actions juste avant ou juste après la conquête d’une base, en version plus faible ou plus restrictive (souvent avec un sbire déjà présent)\n• Joue un sbire supplémentaire sur la base qui va marquer (3 sbires de force 3 et 1 action), avec -1 de force jusqu’à la fin du tour\n• Donne +3 de force jusqu’à la fin du tour (+2 avant une conquête), +1 par autre sbire avec une action posée sur un sbire, et +1 au sbire de force 5 à chaque carte à capacité spéciale jouée\n• Pioche et trie sa pioche : choisit 1 carte parmi les 3 premières, cherche un sbire ou une action, pioche 2 cartes y compris après la conquête d’une base\n• Protège 4 sbires de force 2 de la destruction par les cartes adverses, retire 2 de force à un sbire en annulant ses capacités, et replace un de tes sbires sur la pioche de son propriétaire après la conquête de sa base", en: "• Plays its minions and actions right before or right after a base scores, in a weaker or more restricted version (often with a minion already there)\n• Plays an extra minion on the scoring base (3 power-3 minions and 1 action), with -1 power until the end of the turn\n• Gives +3 power until the end of the turn (+2 before a base scores), +1 per other minion with an action played on a minion, and +1 to the power-5 minion for each card with a special ability you play\n• Draws and sorts its deck: picks 1 of the top 3 cards, searches for a minion or an action, draws 2 cards even after a base scores\n• Protects 4 power-2 minions from destruction by opposing cards, takes 2 power away from a minion while cancelling its abilities, and puts one of your minions from a scored base on top of its owner's deck", statut: "a-verifier" },

  // Ultimates
  ULT: { fr: "• Déplace ses sbires d’une base à l’autre (un seul, jusqu’à 3 vers une même base, ou autant qu’on veut vers d’autres bases), et même un sbire adverse, avec 3 sbires à talent et 6 actions\n• Gagne de la force à chaque déplacement : +1 pour les sbires de force 2 qui se déplacent, +1 pour les sbires de force 3 à chaque sbire qui arrive sur leur base ou la quitte, et +1 aux autres sbires de la base d’arrivée quand le sbire de force 5 bouge\n• Donne de la force avec des actions : +2 à un sbire (qui peut ensuite bouger), ou +1 à chacun des 3 sbires déplacés vers une base\n• Pioche une carte en jouant une action posée sur une base, puis une carte à chaque fois que tu y déplaces des sbires ; replace des cartes de ta main sous ta pioche pour en piocher une de plus que ce que tu as replacé\n• Joue un sbire supplémentaire sur une base où tu n’as aucun sbire, et peut déplacer un de tes sbires juste avant la conquête d’une base", en: "• Moves its minions from base to base (just one, up to 3 to the same base, or any number to other bases), and even an opposing minion, with 3 talent minions and 6 actions\n• Gains power on every move: +1 for power-2 minions that move, +1 for power-3 minions each time another minion moves to or from their base, and +1 for the other minions on the destination base when the power-5 minion moves\n• Boosts power with actions: +2 to a minion (which can then move), or +1 to each of up to 3 minions moved to a base\n• Draws a card when you play an action on a base, then another each time you move minions there; puts cards from your hand under your deck to draw one more than you put back\n• Plays an extra minion on a base where you have none, and can move one of your minions right before a base scores", statut: "a-verifier" },

  // Anciens Incas
  AIN: { fr: "Piochez, jouez et rejouez des actions sur des bases qui activent des capacités déclenchées à chaque fois que vous jouez une action sur des bases, surtout sur la même base", en: "Draw, play and replay actions on bases that trigger abilities each time you play an action on bases, especially on the same base", statut: "a-verifier" },

  // Contes d'Anansi
  ANA: { fr: "• Donnez des cartes à d'autres joueurs pour en tirer profit\n• Obtenez des avantages lorsqu'ils les jouent ou les défaussent\n• Offrez des actions qui sont continuellement échangées entre les joueurs", en: "• Give cards to other players to profit from it\n• Gain benefits when they play or discard them\n• Offer actions that are constantly passed between players", statut: "a-verifier" },

  // Contes de Grimm
  GRI: { fr: "Jouez avec une équipe composée de plusieurs paires de sbires qui ne peuvent travailler que lorsqu'ils sont ensemble avec leur partenaire", en: "Play with a team made up of several pairs of minions that only work when together with their partner", statut: "a-verifier" },

  // Contes Féeriques Russes
  CFR: { fr: "Remplacez n'importe quels sbires en jeu par d'autres, généralement des sbires aléatoires joués depuis le sommet du deck de leur propriétaire", en: "Replace any minions in play with others, usually random minions played from the top of their owner's deck", statut: "a-verifier" },

  // Voyageurs Polynésiens
  VPO: { fr: "• Déplacez-vous vers des bases où vous n'avez pas encore de sbire\n• Gagnez de la puissance et des marqueurs +1 de puissance grâce aux actions jouées sur les sbires\n• Ajoutez des bases supplémentaires en jeu", en: "• Move to bases where you don't have a minion yet\n• Gain power and +1 power counters from actions played on minions\n• Add extra bases to the game", statut: "a-verifier" },

  // Moutons
  MOT: { fr: "• Déplace les créatures quand une créature se déplace\n• Déplace tes créatures, et parfois les autres\n• Pioche en plus et joue les cartes actions\n• Copie et joue les actions des adversaires", en: "• Moves minions when a minion moves\n• Moves your minions, and sometimes others'\n• Draws extra and plays action cards\n• Copies and plays opponents' actions", statut: "a-verifier" },

  // Aladdin
  ALA: { fr: "• Enchaîne les recherches dans la pioche et la défausse : un sbire de force 5 va chercher une action qui trouve un sbire de force 3, lequel cherche les 3 actions à usage unique\n• Joue 2 cartes en plus ou donne +5 de force à un sbire avec chacune de ces actions à usage unique, à condition d’avoir en jeu le sbire qui les cherche\n• Défausse des actions pour en tirer des bénéfices : une action en plus, +2 de force à un sbire de force 3, ou un jeton +1 sur chaque sbire de force 2 de la base\n• Pioche des actions (toutes celles des 4 premières cartes de ta pioche, ou la première trouvée) et récupère des actions de ta défausse, en main ou sur ta pioche\n• Fait défausser une action à chaque adversaire pour en jouer une, joue une action de la défausse d’un autre joueur, et déplace jusqu’à 3 de tes sbires d’une base à une autre", en: "• Chains searches through your deck and discard pile: a power-5 minion fetches an action that finds a power-3 minion, which fetches the 3 one-time-use actions\n• Plays 2 extra cards or gives +5 power to a minion with each of these one-time-use actions, as long as the minion that fetches them is in play\n• Discards actions for benefits: an extra action, +2 power to a power-3 minion, or a +1 counter on each power-2 minion on the base\n• Draws actions (all of those among the top 4 cards of your deck, or the first one found) and recovers actions from your discard pile, into your hand or onto your deck\n• Makes each opponent discard an action so you can play one of them, plays an action from another player's discard pile, and moves up to 3 of your minions from one base to another", statut: "a-verifier" },

  // Beauty and the Beast
  BAB: { fr: "• 11 cartes sur 20 (les 6 sbires de force 2 et 5 actions) se jouent toutes seules quand elles sont défaussées de la main, quelle qu’en soit la raison, même à cause de la limite de 10 cartes\n• Trois sbires de force 3 défaussent une carte pour jouer une action en plus, un sbire de force 3 ou moins en plus, ou piocher une carte\n• Pioche pour refaire sa main : le sbire de force 5 pioche jusqu’à 3 cartes si le sbire de force 4 est là, 2 actions piochent 2 cartes pour n’en défausser qu’une, une action sur une base fait piocher quand tu défausses et une autre te laisse regarder le dessus de ta pioche\n• Se renforce modestement : le sbire de force 4 gagne des jetons +1 (et en donne un au sbire de force 5 s’ils sont ensemble), une action donne +1 jusqu’à la fin du tour aux sbires d’une base\n• Rejoue ses sbires et ralentit la conquête : une action remélange jusqu’à 2 sbires de la défausse dans la pioche, une autre fait jouer un sbire de force 3 ou moins en plus, et une action sur une base relève le seuil de conquête tant qu’elle y reste", en: "• 11 cards out of 20 (the 6 power-2 minions and 5 actions) play themselves when discarded from your hand, for any reason, even because of the 10-card hand limit\n• Three power-3 minions discard a card to play an extra action, an extra minion of power 3 or less, or to draw a card\n• Draws to refill your hand: the power-5 minion draws up to 3 cards if the power-4 minion is there, 2 actions draw 2 cards and discard only one, an action on a base draws when you discard and another lets you look at the top of your deck\n• Gets stronger modestly: the power-4 minion gains +1 counters (and gives one to the power-5 minion if they are together), an action gives +1 until end of turn to the minions on a base\n• Replays its minions and slows scoring: an action shuffles up to 2 minions from the discard pile back into your deck, another plays an extra minion of power 3 or less, and an action on a base raises the base's breakpoint while it stays there", statut: "a-verifier" },

  // Big Hero 6
  BIG: { fr: "• Pose des jetons +1 en masse : 2 actions en posent 2 au total, une autre en pose sur chacun de tes sbires qui n’en ont pas (ou déplace tes jetons), une joue un sbire de force 3 ou moins en supplément avec un jeton dessus, et Hiro Hamada en pose ou en déplace\n• Améliore les sbires qui ont un jeton : Go Go Tomago déplace aussi un autre sbire, Honey Lemon peut jouer une action en plus au lieu de détruire un modificateur, Wasabi gagne +1 de force (ou +1 par jeton, jusqu’à +5) pour le tour, et un autre sbire déplace un de tes sbires après la conquête\n• Profite du nombre de sbires à jeton : Team Effort, 2 Version 2.0 et Yokai progressent avec le nombre de tes sbires qui ont un jeton, et Version 2.0 gonfle la force de tes sbires d’une base jusqu’à la fin du tour\n• Joue en essaim : 4 Microbot Swarm de force 2 remettent un Microbot Swarm de la défausse en main, et Control Mask (modificateur de sbire) cherche un Microbot Swarm dans la pioche puis permet d’en jouer un en supplément ou d’en déplacer\n• Gêne les sbires sans jeton : Yokai (base) donne -1 de force aux sbires sans jeton de sa base, les tiens compris, et permet de déplacer des jetons après la conquête ; Honey Lemon peut détruire un modificateur de base ou de sbire de sa base", en: "• Places +1 counters in bulk: 2 actions place 2 in total, another places one on each of your minions without one (or moves your counters), one plays an extra minion of power 3 or less with a counter on it, and Hiro Hamada places or moves counters\n• Upgrades minions that have a counter: Go Go Tomago also moves another minion, Honey Lemon can play an extra action instead of destroying a modifier, Wasabi gains +1 power (or +1 per counter, up to +5) for the turn, and another minion moves one of your minions after a base scores\n• Scales with minions that have counters: Team Effort, 2 Version 2.0 and Yokai grow with the number of your minions that have a counter, and Version 2.0 boosts the power of your minions at a base until the end of the turn\n• Plays in a swarm: 4 power-2 Microbot Swarms put a Microbot Swarm from your discard pile into your hand, and Control Mask (minion modifier) searches your deck for a Microbot Swarm, then lets you play an extra one or move them\n• Hinders minions without counters: Yokai (base) gives -1 power to minions without counters at its base, yours included, and lets you move counters after the base scores; Honey Lemon can destroy a base or minion modifier at her base", statut: "a-verifier" },

  // Frozen
  FRO: { fr: "• Chaîne ses sbires entre eux : Anna cherche Elsa ou Kristoff dans la pioche ou la défausse, Elsa joue Olaf ou un Snowgie depuis la main ou la défausse en sbire supplémentaire (ou remet Marshmallow en main depuis la défausse)\n• Rejoue depuis la défausse : une action joue Olaf, Marshmallow ou un Snowgie en supplément, une autre détruit un de tes sbires pour en jouer un autre de ta défausse en supplément, une troisième défausse une carte pour remettre un sbire de ta défausse en main\n• Cherche des sbires et prépare sa main : 2 actions cherchent n’importe quel sbire dans la pioche ou la défausse, Olaf regarde les 2 premières cartes de la pioche et 2 autres actions les 3 premières\n• Gagne de la force selon ses sbires : 4 Snowgies de force 2 posent un jeton +1 sur eux si un de tes sbires de leur base a une force de 5 ou plus, Kristoff gagne +2 avec Anna ou Sven et Marshmallow +2 avec Elsa\n• Protège ses sbires et gêne les adversaires : une action de base et un sbire empêchent la destruction de tes sbires par les cartes adverses, une autre action de base gêne les adversaires qui veulent y jouer des sbires", en: "• Chains its minions together: Anna searches your deck and/or discard pile for Elsa or Kristoff, Elsa plays Olaf or a Snowgie from your hand or discard pile as an extra minion (or puts Marshmallow from your discard pile into your hand)\n• Replays from the discard pile: one action plays Olaf, Marshmallow or a Snowgie as an extra minion, another destroys one of your minions to play a different one from your discard pile as an extra, a third discards a card to put a minion from your discard pile into your hand\n• Searches for minions and sets up its hand: 2 actions search for any minion in your deck and/or discard pile, Olaf looks at the top 2 cards of your deck and 2 other actions look at the top 3\n• Gains power from its minions: 4 power-2 Snowgies place a +1 counter on themselves if one of your minions at their base has power 5 or more, Kristoff gets +2 with Anna or Sven and Marshmallow +2 with Elsa\n• Protects its minions and hinders opponents: a base action and a minion stop your minions from being destroyed by opposing cards, another base action hinders opponents who want to play minions there", statut: "a-verifier" },

  // Mulan
  MUL: { fr: "• Pose des jetons +1 en masse : 2 sbires de force 4 (talent) et 3 sbires de force 2 en posent sur un autre sbire de leur base, une action sur une base en pose sur 2 sbires, une autre sur chacun de tes sbires, 2 autres en posent 2 sur un sbire ; une action posée sur un sbire augmente aussi sa force\n• Fait des jetons +1 un déclencheur : Mulan, Ling, Yao et Chien Po ne s’activent que quand un jeton leur est posé, une fois par tour (même pendant le tour des autres) ; Mulan joue une action en plus ou pioche, Ling pioche, et les autres peuvent aussi faire piocher\n• Détruit les sbires de faible force : 2 actions détruisent un sbire de force 3 ou moins, un sbire de force 3 peut détruire un sbire de force 2 ou moins de sa base, une action avant la conquête détruit un sbire de force inférieure ou égale à celle d’un de tes sbires, et une autre renvoie dans leurs pioches les sbires de force 3 ou moins d’une base (contre une défausse)\n• Protège et déploie ses sbires : un sbire de force 3 rend tes sbires de sa base insensibles aux cartes adverses jusqu’à ton prochain tour, et 3 cartes font jouer un sbire en plus (force 2, 3 ou 4 selon la carte, la dernière pouvant aussi faire piocher 2 cartes)", en: "• Places +1 counters en masse: 2 power-4 minions (talent) and 3 power-2 minions place them on another minion at their base, an action on a base places them on 2 minions, another on each of your minions, 2 others place 2 on a minion; an action played on a minion also raises its power\n• Makes +1 counters a trigger: Mulan, Ling, Yao and Chien Po only work when a counter is placed on them, once per turn (even during other players' turns); Mulan plays an extra action or draws, Ling draws, and the others can also make you draw\n• Destroys low-power minions: 2 actions destroy a minion of power 3 or less, a power-3 minion can destroy a minion of power 2 or less at its base, an action before a base scores destroys a minion with power less than or equal to one of your minions, and another shuffles the minions of power 3 or less on a base back into their owners' decks (for a discard)\n• Protects and deploys its minions: a power-3 minion makes your minions at its base immune to other players' cards until your next turn, and 3 cards play an extra minion (power 2, 3 or 4 depending on the card, the last one can also draw 2 cards)", statut: "a-verifier" },

  // The Lion King
  LIK: { fr: "• Fait vivre sa défausse : Mufasa (force 6) pose jusqu’à 4 jetons +1 sur tes sbires quand il va en défausse, Simba gagne +2 de force si Mufasa est dans ta défausse et Nala +2 si un Lion Cub l’est, et Simba peut retourner dans ta pioche\n• Cherche des remplaçants quand ses sbires quittent le jeu : 4 Lion Cubs de force 2 cherchent un sbire de force 4 ou moins dans la pioche après être allés en défausse, ce qui se déclenche aussi quand leur base marque\n• Rejoue et échange ses sbires : 2 Circle of Life (modificateur de sbire) font jouer un sbire de la main ou de la défausse quand le sbire modifié va en défausse, 2 Wildebeest Stampede détruisent un de tes sbires pour en chercher un dans la pioche et le jouer en supplément, et Timon et Pumbaa (force 3) remettent une carte de ta défausse sous la pioche\n• Pioche, renforce et élimine : Hakuna Matata pioche 2 cartes, Just Can’t Wait to Be King pose 2 jetons +1 sur un de tes sbires, He Lives In You (base) augmente la force, et The Hyenas détruit un sbire de force 3 ou moins", en: "• Makes its discard pile work: Mufasa (power 6) places up to 4 +1 counters on your minions when he goes to the discard pile, Simba gets +2 power if Mufasa is in your discard pile and Nala +2 if a Lion Cub is, and Simba can return to your deck\n• Fetches replacements when its minions leave play: 4 power-2 Lion Cubs search your deck for a minion of power 4 or less after going to the discard pile, which also triggers when their base scores\n• Replays and swaps its minions: 2 Circle of Life (minion modifier) play a minion from your hand or discard pile when the modified minion goes to the discard pile, 2 Wildebeest Stampede destroy one of your minions to search your deck for one and play it as an extra, and Timon and Pumbaa (power 3) put a card from your discard pile on the bottom of your deck\n• Draws, boosts and eliminates: Hakuna Matata draws 2 cards, Just Can't Wait to Be King places 2 +1 counters on one of your minions, He Lives In You (base) raises power, and The Hyenas destroys a minion of power 3 or less", statut: "a-verifier" },

  // The Nightmare Before Christmas
  NBC: { fr: "• Mise sur les modificateurs de sbire : 8 cartes sur 20 en sont, jouables sur tes sbires comme sur ceux des autres, dont Sandy Claws Costume (+1 de force par modificateur que tu contrôles), 2 Monster Garland (+3 de force sur ton sbire, -2 sur un sbire que tu ne contrôles pas) et Oogie Boogie (met la force du sbire à 0)\n• Recycle et joue ses modificateurs : Jack Skellington (force 5) remet un modificateur de ta défausse en main, Winter Surprise en joue un depuis la défausse en action en plus, Sally (force 4) en joue un en action en plus, et Lock, Shock & Barrel (force 3) en jouent un avant la conquête de leur base\n• Déplace et exploite ses modificateurs : Finkelstein (force 4) déplace un modificateur d’un sbire à un autre, The Mayor of Halloween Town donne +1 de force à tes sbires de sa base si tu y contrôles un modificateur, et Zero (force 0) gagne +3 de force si tu en contrôles un là\n• Espionne les adversaires : Christmas Will Be Ours! permet de regarder la main d’un autre joueur", en: "• Bets on minion modifiers: 8 of its 20 cards are modifiers, played on your own minions or on others', including Sandy Claws Costume (+1 power per modifier you control), 2 Monster Garland (+3 power on your minion, -2 on one you don't control) and Oogie Boogie (sets the minion's power to 0)\n• Recycles and plays its modifiers: Jack Skellington (power 5) puts a modifier from your discard pile into your hand, Winter Surprise plays one from your discard pile as an extra action, Sally (power 4) plays one as an extra action, and Lock, Shock & Barrel (power 3) play one before their base scores\n• Moves and exploits its modifiers: Finkelstein (power 4) moves a modifier from one minion to another, The Mayor of Halloween Town gives +1 power to your minions at its base if you control a modifier there, and Zero (power 0) gets +3 power if you control one there\n• Spies on opponents: Christmas Will Be Ours! lets you look at another player's hand", statut: "a-verifier" },

  // Wreck-It Ralph
  WIR: { fr: "• Mise sur les modificateurs de base : 7 cartes sur 20 en sont, Wreck-It Ralph (force 5) en joue un sur sa base en action en plus ou en détruit un, Fix-It Felix Jr. (force 4) remet un modificateur de base de ta défausse en main, et 3 Sergeant Calhoun (force 3) donnent +1 de force à tes autres sbires de leur base si tu y as un modificateur de base\n• Déplace ses sbires pour les renforcer : 4 Sugar Rush Racer de force 2 peuvent aller vers ou depuis la base d’un modificateur de base que tu viens de jouer pour gagner +1 de force jusqu’à la fin du tour, Vanellope Von Schweetz change de base et gagne un jeton +1, et Sugar Rush (base) déplace jusqu’à 2 de tes sbires depuis ou vers sa base\n• Fuit et regroupe les sbires : 2 Escape Pod déplacent des sbires d’une même base vers une même autre base pour les garder après la conquête, et Research Lab Beacon rassemble sur sa base tous les sbires d’une faction, quel que soit leur contrôleur\n• Casse les bases adverses : Cy-Bug Infestation et Mints Eruption permettent de remplacer ou de détruire une base sans la faire marquer, idéal contre une base où les adversaires dominent", en: "• Bets on base modifiers: 7 of its 20 cards are base modifiers, Wreck-It Ralph (power 5) plays one at his base as an extra action or destroys one there, Fix-It Felix Jr. (power 4) puts a base modifier from your discard pile into your hand, and 3 Sergeant Calhouns (power 3) give +1 power to your other minions at their base if you have a base modifier there\n• Moves its minions to power them up: 4 power-2 Sugar Rush Racers can move to or from the base of a base modifier you just played to get +1 power until the end of the turn, Vanellope Von Schweetz changes base and gets a +1 counter, and Sugar Rush (base) moves up to 2 of your minions from or to its base\n• Flees and regroups minions: 2 Escape Pods move minions from one base to another to keep them after a base scores, and Research Lab Beacon moves all minions of a faction to its base, whoever controls them\n• Wrecks opposing bases: Cy-Bug Infestation and Mints Eruption let you replace or destroy a base without scoring it, ideal against a base where opponents are ahead", statut: "a-verifier" },

  // Pingouins
  PIN: { fr: "• Jouez des sbires supplémentaires aléatoires directement depuis votre deck\n• Déclenche des capacités à chaque fois que vous jouez un sbire de cette manière", en: "• Play extra random minions directly from your deck\n• Triggers abilities each time you play a minion this way", statut: "a-verifier" },

  // Teens
  TEE: { fr: "• Synergie entre les différentes créatures\n• Que des créatures à 3 de force\n• Multiples effets de renforcement sur les créatures", en: "• Synergy between the different minions\n• Only power-3 minions\n• Multiple power-boost effects on minions", statut: "a-verifier" },

  // Traqueurs de Spectres
  TDS: { fr: "• Pose des actions « Spectre » sur les bases (6 cartes) : chacune augmente de 3 le seuil de conquête de la base et rapporte un bonus quand elle est détruite\n• Détruit ses propres actions posées sur les bases pour en tirer des avantages : seuil abaissé de 3, jeton +1, action en plus, force en plus pour ses sbires ou pioche d’une carte\n• Transfère des actions d’une base à une autre, à ton tour ou avant la conquête, ou les détruit ; une action déplace aussi un de tes sbires et détruit une action sur la nouvelle base\n• Pioche des cartes : 3 d’un coup quand certains spectres sont détruits, 1 avec le sbire de force 5, et cherche un spectre ou n’importe quelle carte pour la mettre en main ou sur la pioche\n• Stocke sous ses spectres des sbires de force 3 ou moins (main ou défausse) ou des actions de la défausse, et les joue en plus quand le spectre quitte le jeu", en: "• Plays \"Wraith\" actions on bases (6 cards): each one raises the base's breakpoint by 3 and gives a bonus when it is destroyed\n• Destroys its own actions played on bases for benefits: breakpoint lowered by 3, a +1 counter, an extra action, extra power for its minions or a card drawn\n• Transfers actions from one base to another, on your turn or before a base scores, or destroys them; one action also moves one of your minions and destroys an action on the new base\n• Draws cards: 3 at once when some Wraiths are destroyed, 1 with the power-5 minion, and searches for a Wraith or any card to put in your hand or on top of your deck\n• Stores minions of power 3 or less (from hand or discard pile) or actions from your discard pile under its Wraiths, and plays them as extras when the Wraith leaves play", statut: "a-verifier" },

  // Extramorphes
  EXT: { fr: "• Joue des sbires en plus depuis le dessus de la pioche : un sbire de force 3 ou 4 à la place d’un sbire de force 2, un sbire de force choisie (jusqu’à 4), ou de force 2 ou moins avec des actions posées sur une base\n• Transforme des sbires de force 3 ou moins (les siens ou ceux des adversaires) : l’action qui les porte les détruit puis joue à leur place un sbire du dessus de la pioche ; un sbire de force 4 en détruit aussi un à son arrivée\n• Détruit une base et toutes les cartes qui s’y trouvent avec une action posée dessus, au tour suivant\n• Déplace des sbires : n’importe quel sbire avec une action, un sbire adverse de force 3 ou moins avec 3 sbires de force 3, ou ses sbires de force 4 en retirant un jeton +1\n• Cherche ses cartes clés (une action sur une base avec le sbire de force 5, une action sur un sbire avec cette action), trie le dessus de la pioche, remélange jusqu’à 3 cartes de la défausse dans la pioche et affaiblit de 1 les sbires adverses sur certaines bases", en: "• Plays extra minions off the top of your deck: a power-3 or power-4 minion in place of a power-2 minion, a minion of a chosen power (up to 4), or of power 2 or less with actions played on a base\n• Transforms minions of power 3 or less (yours or your opponents'): the action on them destroys them and plays a minion off the top of your deck in their place; a power-4 minion also destroys one when it arrives\n• Destroys a base and all the cards on it with an action played on it, on the following turn\n• Moves minions: any minion with an action, an opponent's minion of power 3 or less with 3 power-3 minions, or its own power-4 minions by removing a +1 counter\n• Searches for its key cards (an action on a base with the power-5 minion, an action on a minion with that action), sorts the top of your deck, shuffles up to 3 cards from your discard pile into your deck and weakens opponents' minions by 1 on some bases", statut: "a-verifier" },

  // Hommes d'Action
  HDA: { fr: "• 6 sbires uniques de force 5 et 14 actions ; presque tout fonctionne quand tu n’as qu’un seul sbire sur la base, avec +2 ou +4 de force en continu, +2 jusqu’à la fin du tour ou des jetons +1\n• Abaisse le seuil de conquête d’une base (jusqu’à 5), le plus souvent quand tu n’y as qu’un seul sbire, pour marquer avec un seul gros sbire\n• Joue des actions en plus (jusqu’à 2 en défaussant une carte, ou stockées sous un sbire, même avant la conquête), un sbire en plus sur une base sans sbire à toi, ou déplace un sbire avec une action en plus s’il est seul\n• Pioche (1 carte par tour avec un sbire seul, ou 1 par base où tu es seul) et cherche un sbire dans ta pioche pour le placer dessus\n• Avant ou après la conquête : détruit un sbire de force imprimée 3 ou moins de chaque adversaire sur une base où tu es seul, ou ramène un de tes sbires en main ; protège aussi tes sbires des actions adverses sur une base", en: "• 6 unique power-5 minions and 14 actions; almost everything works when you have only one minion on the base, with +2 or +4 power on a continuous basis, +2 power until the end of the turn or +1 counters\n• Lowers a base's breakpoint (by up to 5), most often when you have only one minion there, to score with a single big minion\n• Plays extra actions (up to 2 by discarding a card, or stored under a minion, even before a base scores), an extra minion on a base where you have none, or moves a minion with an extra action if it is alone\n• Draws cards (1 per turn with a lone minion, or 1 per base where you are alone) and searches your deck for a minion to place on top of it\n• Before or after a base scores: destroys a minion of printed power 3 or less controlled by each opponent on a base where you are alone, or returns one of your minions to your hand; also shields your minions from other players' actions on a base", statut: "a-verifier" },

  // Retourneurs du Futur
  RDF: { fr: "• Met des cartes en stase (jetons de stase) pour les jouer gratuitement et en plus lors d’un tour suivant : cartes de la main, ou parmi les 2 ou 3 premières cartes de la pioche\n• Ajoute ou retire des jetons de stase pour retarder ou accélérer ses cartes, au début du tour ou avec ses sbires et ses actions\n• Pose des jetons +1 sur ses sbires dès qu’un jeton de stase est retiré, et à l’entrée en jeu des 4 sbires de force 2 sortis de stase\n• Pioche quelques cartes (1 avec deux actions, 1 par jeton retiré d’une autre action) et cherche ou récupère une carte de la pioche ou de la défausse pour la jouer en plus plus tard\n• Abaisse le seuil de conquête d’une base de 1 par jeton de stase placé sur une action (jusqu’à 5)", en: "• Puts cards into stasis (stasis counters) to play them for free as extras on a later turn: cards from your hand, or among the top 2 or 3 cards of your deck\n• Adds or removes stasis counters to delay or speed up its cards, at the start of your turn or with its minions and actions\n• Places +1 counters on its minions whenever a stasis counter is removed, and when the 4 power-2 minions enter play from stasis\n• Draws a few cards (1 with two actions, 1 per counter removed from another action) and searches for or recovers a card from your deck or discard pile to play it as an extra later\n• Lowers a base's breakpoint by 1 for each stasis counter on an action (up to 5)", statut: "a-verifier" },

  // Champions du Monde
  CDM: { fr: "Cette faction réunis des cartes de pleins d'autres factions existantes", en: "This faction brings together cards from many other existing factions", statut: "a-verifier" },

  // Gobelins
  GOB: { fr: "• Faction porté sur le hasard et la chance\n• Munissez-vous d'une pièce de monnaie pour jouer", en: "• A faction built on randomness and luck\n• Grab a coin to play", statut: "a-verifier" },

  // Sirènes
  SIR: { fr: "• Déplacer vos créatures et celles de vos adversaires\n• Empêcher vos adversaires d'ajouter leur force à une base", en: "• Move your minions and your opponents'\n• Prevent your opponents from adding their power to a base", statut: "a-verifier" },

  // Squelettes
  SQU: { fr: "Enterre les cartes pour surprendre vos adversaires", en: "Buries cards to surprise your opponents", statut: "a-verifier" },

  // Adolescent Epic Geckos
  GEC: { fr: "• Enchaîne les actions : 8 actions sur 10 donnent une action en plus si c’est la première jouée du tour, avec souvent un bonus différent sinon (carte, déplacement, jetons ou force)\n• Place beaucoup de jetons +1 sur ses sbires, surtout à partir de la deuxième action jouée dans le tour, et donne parfois +2 de force jusqu’à la fin du tour\n• Échange ses sbires en jeu contre un sbire de nom différent : un sbire de force 4 contre un sbire de la main ou de la pioche, ou n’importe quel sbire de force égale ou inférieure depuis la main, la pioche ou la défausse\n• Pioche des cartes, remet des actions standard de la défausse dans la pioche et peut les stocker sous un sbire pour les remélanger plus tard\n• Déplace ses sbires (ou n’importe quel sbire), et peut ramener un sbire en main au lieu de le laisser perdu après une base perdue", en: "• Chains actions: 8 actions out of 10 give an extra action if it is the first one played this turn, often with a different bonus otherwise (card, movement, counters or power)\n• Places many +1 counters on its minions, especially from the second action played in a turn, and sometimes gives +2 power until the end of the turn\n• Swaps its minions in play for a minion with a different name: a power-4 minion for one from your hand or deck, or any minion of equal or lower power from your hand, deck or discard pile\n• Draws cards, shuffles standard actions from your discard pile back into your deck and can store them under a minion to reshuffle them later\n• Moves its minions (or any minion), and can return a minion to your hand instead of losing it after a base you didn't win scores", statut: "a-verifier" },

  // G.I. Gerald
  GIG: { fr: "• 17 cartes « Fusion » sur 20 : chacune se joue comme sbire (de force 2 ou 4) ou comme action, avec un effet différent selon la façon dont elle est jouée\n• Joue des sbires de force 2 ou moins et des actions en plus avec ses fusions et une action, parfois les deux à la fois\n• Place des jetons +1 sur ses sbires et donne de la force jusqu’à la fin du tour (+1, +3, ou +2 aux sbires joués ce tour sur une base) ; le sbire de force 5 gagne de la force quand une fusion est jouée en action\n• Pioche 1 ou 2 cartes avec 3 fusions, remélange des sbires ou des actions de la défausse dans la pioche, copie l’action d’une autre fusion (même avant la conquête d’une base) ou ramène une fusion en main pour la rejouer\n• Déplace un sbire, ou place un sbire de force 3 ou moins sous la pioche de son propriétaire", en: "• 17 \"Fusion\" cards out of 20: each one is played as a minion (power 2 or 4) or as an action, with a different effect depending on how it is played\n• Plays extra minions of power 2 or less and extra actions with its fusions and one action, sometimes both at once\n• Places +1 counters on its minions and gives power until the end of the turn (+1, +3, or +2 to minions played this turn on a base); the power-5 minion gains power when a fusion is played as an action\n• Draws 1 or 2 cards with 3 fusions, shuffles minions or actions from your discard pile back into your deck, copies the action of another fusion (even before a base scores) or returns a fusion to your hand to replay it\n• Moves a minion, or places a minion of power 3 or less on the bottom of its owner's deck", statut: "a-verifier" },

  // Pearl and the Images
  PEA: { fr: "• Réagit à la force adverse : quand un sbire adverse gagne de la force, tes 4 sbires de force 2 peuvent se mettre un jeton +1 ou rejoindre sa base (si tu y as un sbire), une fois par tour ; 2 actions sur un sbire lui donnent +3 jusqu’à fin du tour\n• Pose des jetons +1 en les partageant : un sbire à talent en met un chez un adversaire pour en mettre un chez toi, et une action en place sur autant de sbires adverses que tu veux, avec un jeton +1 chez toi par sbire ciblé\n• Donne de la force à tous pour en profiter : 3 sbires et une action sur une base donnent +1 à tous les sbires ici jusqu’à fin du tour ; le sbire de force 5 donne +1 à un sbire ici ou pioche un sbire de force ≤2\n• Entraide intéressée : 2 actions sur une base font jouer un sbire de force ≤2 en plus à un joueur (si c’est un adversaire, tu pioches ou poses un jeton +1) ; une autre fait piocher les joueurs volontaires (toi une carte par joueur) ; une remélange les sbires de force ≤2 des défausses\n• Contrôle léger, sans destruction : une action déplace un de tes sbires et un sbire adverse vers une autre base (ou, avant la conquête, vers la base qui marque) ; une autre réduit les sbires adverses d’une base à leur force imprimée, jouable avant la conquête là où tu as le plus de sbires", en: "• Reacts to opposing power gains: when an opposing minion gains power, your 4 power-2 minions can put a +1 counter on themselves or move to its base (if you have a minion there), once per turn; 2 actions on a minion give it +3 until end of turn\n• Places +1 counters by sharing them: a talent minion puts one on an opposing minion to put one on yours, and an action places them on as many opposing minions as you like, with a +1 counter on your side for each minion targeted\n• Boosts everyone to profit from it: 3 minions and an action on a base give +1 to every minion here until end of turn; the power-5 minion gives +1 to a minion here or draws a minion of power 2 or less\n• Self-interested teamwork: 2 actions on a base let a player play an extra minion of power 2 or less (if it is an opponent, you draw a card or place a +1 counter); another makes willing players draw (you draw one card per player); one shuffles minions of power 2 or less from the discard piles back\n• Light control, no destruction: one action moves one of your minions and an opposing minion to another base (or, before scoring, to the base about to score); another reduces opposing minions on a base to their printed power, playable before scoring where you have the most minions", statut: "a-verifier" },

  // Rulers of the Cosmos
  RTC: { fr: "• Pose beaucoup d’actions sur ses sbires (7 actions sur 20), qui donnent chacune une capacité « Talent » au sbire : se déplacer, placer un jeton +1, être immunisé aux cartes adverses, gagner de la force selon les joueurs présents ou piocher\n• Transfère ses actions d’un sbire à un autre, même avant la conquête d’une base, avec un jeton +1 sur chaque sbire qui en reçoit une ; un sbire peut aussi copier le talent d’un autre sbire ou d’une action\n• Joue des actions en plus : une action sur un sbire qui n’en porte pas, une action sur sbire prise dans n’importe quelle défausse (puis remise sous la pioche de son propriétaire), ou une action sur sbire reprise en main depuis un sbire ou ta défausse\n• Pioche des actions sur sbire dans la pioche, remet une action dans la pioche quand le sbire qui la porte quitte le jeu, et pioche 1 carte avec une action qui reste seule sur son sbire\n• Échange un sbire de force 2 portant une épée contre un sbire de force 5 ou plus (main, pioche ou défausse), et donne de la force à un sbire de force imprimée 5 ou plus portant une épée", en: "• Plays many actions on its minions (7 actions out of 20), each giving the minion a \"Talent\" ability: moving itself, placing a +1 counter, being immune to opposing cards, gaining power based on the players present, or drawing a card\n• Transfers its actions from one minion to another, even before a base scores, with a +1 counter on each minion that receives one; a minion can also copy the talent of another minion or of an action\n• Plays extra actions: an action on a minion that has none, an action on a minion taken from any player's discard pile (then put back on the bottom of its owner's deck), or an action on a minion returned to your hand from a minion or your discard pile\n• Draws actions on minions from your deck, puts an action back in your deck when the minion carrying it leaves play, and draws 1 card with an action that stays alone on its minion\n• Swaps a power-2 minion carrying a Sword for a minion of power 5 or more (from hand, deck or discard pile), and gives extra power to a minion of printed power 5 or more carrying a Sword", statut: "a-verifier" },

  // Slashers
  SLA: { fr: "• 5 sbires uniques de force 5 (des Slashers) : chacun va chercher dans la pioche ou la défausse « son » équipement, une action qui se pose sur un sbire\n• Détruit les sbires adverses de faible force : avant la conquête d’une base, après un déplacement, quand un jeton +1 est posé, ou avec une action (force imprimée 3 ou moins, voire 1 seule pour le talent qui affaiblit aussi les adversaires de -1)\n• Se renforce en détruisant : un jeton +1 à chaque début de tour, un autre quand un sbire est détruit, la force du sbire détruit, +3 jusqu’à la fin du tour, et une action en plus après une destruction\n• Se déplace vers les sbires adverses (équipements qui font changer de base, action qui déplace un de tes sbires) et harcèle : une action posée sur un sbire adverse le fait détruire s’il ne défausse pas une carte et ne s’enfuit pas\n• Cherche et rejoue ses équipements : pioche une action sur un sbire depuis la pioche ou la défausse, ramène un sbire de la défausse en main, pioche quand des sbires sont détruits, et la machette revient en main après une destruction", en: "• 5 unique power-5 minions (Slashers): each one fetches \"its own\" gear from your deck or discard pile, an action played on a minion\n• Destroys weak opposing minions: before a base scores, after a move, when a +1 counter is placed, or with an action (printed power 3 or less, only 1 for the talent that also gives opponents -1)\n• Grows by destroying: a +1 counter at the start of each turn, another when a minion is destroyed, the power of the destroyed minion, +3 until end of turn, and an extra action after a destruction\n• Moves toward opposing minions (gear that changes bases, an action that moves one of your minions) and harasses: an action played on an opposing minion gets it destroyed unless it discards a card and runs away\n• Fetches and replays its gear: draws a play-on-minion action from the deck or discard pile, returns a minion from the discard pile to your hand, draws when minions are destroyed, and the machete returns to hand after a destruction", statut: "a-verifier" },

  // Clowns
  CLO: { fr: "• Rejoue les actions de ta défausse : 4 sbires (dont le plus fort, qui remplace ton action normale) jouent des actions standard de ta défausse, puis les placent sous ta pioche\n• Remplit sa défausse d’actions : 4 sbires de force 2 y placent une action cherchée dans la pioche, un sbire de force 3 pioche une action et défausse l’autre, et une action remélange jusqu’à 2 cartes de la défausse dans la pioche\n• Donne un bonus aux actions jouées depuis la défausse : une action en plus, une carte piochée en plus (contre une défausse), un sbire en plus de force 4 au lieu de 3, ou +4 de force au lieu de +2\n• Pioche des cartes : 2 avec deux de ses actions, 1 après la première action jouée chaque tour avec un sbire de force 4, ou autant que de cartes défaussées (jusqu’à 4)\n• Donne de la force jusqu’à la fin du tour (+2, ou +1 par sbire de la base), déplace jusqu’à 2 de tes sbires d’une base à une autre, et fait défausser à chaque joueur une action parmi les 3 premières cartes de sa pioche", en: "• Replays actions from your discard pile: 4 minions (including the strongest, which replaces your regular action play) play standard actions from your discard pile, then put them on the bottom of your deck\n• Fills its discard pile with actions: 4 power-2 minions put an action searched from your deck there, a power-3 minion draws one action and discards another, and an action shuffles up to 2 cards from the discard pile back into the deck\n• Gives a bonus to actions played from the discard pile: an extra action, an extra card drawn (for a discard), an extra minion of power 4 instead of 3, or +4 power instead of +2\n• Draws cards: 2 with two of its actions, 1 after the first action you play each turn with a power-4 minion, or as many as you discard (up to 4)\n• Gives power until the end of the turn (+2, or +1 per minion on the base), moves up to 2 of your minions from one base to another, and makes each player discard an action among the top 3 cards of their deck", statut: "a-verifier" },

  // ----- Cartes spéciales (voir data/factions.js) : texte vide = pas de bouton « Notes » -----
  // Monstres
  MONSTRES: { fr: "• 20 cartes disponibles — extension Munchkin\n• Apparaissent automatiquement sur certaines bases et augmentent leur seuil de conquête\n• Lorsqu'ils sont détruits, rapportent des trésors selon leur valeur\n• Si une base est conquise, les trésors des monstres survivants sont partagés entre les joueurs présents", en: "• 20 cards available — Munchkin expansion\n• Appear automatically on some bases and raise their breakpoint\n• When destroyed, they reward treasures according to their value\n• If a base scores, the treasures of the surviving monsters are shared among the players present", statut: "a-verifier" },

  // Trésors
  TRESORS: { fr: "• 22 cartes disponibles — extension Munchkin (3 créatures et 19 actions)\n• Récompenses obtenues principalement en détruisant des monstres\n• Jouées comme des créatures ou des actions classiques\n• Permettent d'obtenir des effets supplémentaires et de renforcer son jeu", en: "• 22 cards available — Munchkin expansion (3 minions and 19 actions)\n• Rewards mainly obtained by destroying monsters\n• Played like regular minions or actions\n• Grant extra effects and strengthen your game", statut: "a-verifier" },

  // Démences
  DEMENCE: { fr: "• 30 cartes disponibles — extension Cthulhu Fhtagn !\n• Cartes communes accessibles grâce aux capacités de certaines factions\n• Chaque carte permet de piocher 2 cartes ou de retourner dans la pioche commune\n• Chaque paire conservée en fin de partie fait perdre 1 PV", en: "• 30 cards available — Cthulhu Fhtagn! expansion\n• Shared cards obtained through the abilities of certain factions\n• Each card lets you draw 2 cards or return to the shared deck\n• Each pair kept at the end of the game costs 1 VP", statut: "a-verifier" },
};
